#include <functional>
#include <map>
#include <string>
#include <utility>

class ResourceCache
{
public:
    explicit ResourceCache(std::function<int(const std::string&)> loader) : m_loader{ std::move(loader) } {}

    int acquire(const std::string& name)
    {
        auto it{ m_entries.find(name) };
        if (it == m_entries.end()) it = m_entries.emplace(name, Entry{ m_loader(name), 0 }).first;
        ++it->second.refs;
        return it->second.id;
    }

    void release(const std::string& name)
    {
        const auto it{ m_entries.find(name) };
        if (it == m_entries.end()) return;
        if (--it->second.refs == 0) m_entries.erase(it);      // nobody uses it: unload
    }

    int refCount(const std::string& name) const
    {
        const auto it{ m_entries.find(name) };
        return it == m_entries.end() ? 0 : it->second.refs;
    }

    std::size_t loadedCount() const { return m_entries.size(); }

private:
    struct Entry { int id; int refs; };
    std::function<int(const std::string&)> m_loader;
    std::map<std::string, Entry> m_entries;
};

