#include <vector>
struct FakeLoader { std::vector<std::string>* log; int next{ 100 }; int operator()(const std::string& n) { log->push_back(n); return next++; } };
TEST("loaded once, shared")
{
    std::vector<std::string> log;
    ResourceCache c{ FakeLoader{ &log } };
    const int a{ c.acquire("goblin.png") }, b{ c.acquire("goblin.png") };
    CHECK_EQ(a, b);
    CHECK_EQ(log.size(), std::size_t{ 1 });
    CHECK_EQ(c.refCount("goblin.png"), 2);
}
TEST("unloaded at zero, reloaded later")
{
    std::vector<std::string> log;
    ResourceCache c{ FakeLoader{ &log } };
    c.acquire("a"); c.acquire("a");
    c.release("a"); CHECK_EQ(c.loadedCount(), std::size_t{ 1 });
    c.release("a"); CHECK_EQ(c.loadedCount(), std::size_t{ 0 }); CHECK_EQ(c.refCount("a"), 0);
    c.acquire("a"); CHECK_EQ(log.size(), std::size_t{ 2 });
}
TEST("different names are different resources") { std::vector<std::string> log; ResourceCache c{ FakeLoader{ &log } }; CHECK(c.acquire("x") != c.acquire("y")); CHECK_EQ(c.loadedCount(), std::size_t{ 2 }); }
TEST("releasing what is not loaded does nothing") { std::vector<std::string> log; ResourceCache c{ FakeLoader{ &log } }; c.release("nothing"); CHECK_EQ(c.loadedCount(), std::size_t{ 0 }); }

